import logging
from decimal import Decimal

from sqlalchemy.orm import Session

from ledger_service.app.config import settings
from ledger_service.app.models.ledger import Account

logger = logging.getLogger(__name__)


def get_or_create_account(
    db: Session,
    account_id: str,
    owner_id: str,
    owner_type: str,
    account_type: str,
    currency: str = "usd",
    description: str | None = None,
) -> Account:
    """
    Get existing account or create new one.
    Used to lazily create merchant accounts on first payment.
    """
    account = db.query(Account).filter(Account.id == account_id).first()

    if not account:
        account = Account(
            id=account_id,
            owner_id=owner_id,
            owner_type=owner_type,
            account_type=account_type,
            currency=currency,
            balance=Decimal(0),
            available_balance=Decimal(0),
            pending_balance=Decimal(0),
            description=description,
        )
        db.add(account)
        db.flush()
        logger.info(f"Created account: {account_id} owner={owner_id} type={account_type}")

    return account


def get_merchant_account_id(merchant_id: str, currency: str = "usd") -> str:
    return f"acc_merchant_{merchant_id}_{currency}"


def ensure_system_accounts(db: Session):
    """
    Create platform system accounts if they don't exist.
    Called on startup.
    """
    system_accounts = [
        {
            "id": settings.escrow_account_id,
            "owner_id": "platform",
            "owner_type": "platform",
            "account_type": "liability",
            "description": "Holds funds between capture and merchant payout",
        },
        {
            "id": settings.platform_account_id,
            "owner_id": "platform",
            "owner_type": "platform",
            "account_type": "asset",
            "description": "Platform operating account",
        },
        {
            "id": settings.fee_account_id,
            "owner_id": "platform",
            "owner_type": "platform",
            "account_type": "revenue",
            "description": "Platform fee collection account",
        },
        {
            "id": settings.refund_reserve_account_id,
            "owner_id": "platform",
            "owner_type": "platform",
            "account_type": "liability",
            "description": "Reserve for pending refunds",
        },
    ]

    for acct in system_accounts:
        existing = db.query(Account).filter(Account.id == acct["id"]).first()
        if not existing:
            db.add(Account(
                id=acct["id"],
                owner_id=acct["owner_id"],
                owner_type=acct["owner_type"],
                account_type=acct["account_type"],
                currency="usd",
                balance=Decimal(0),
                available_balance=Decimal(0),
                pending_balance=Decimal(0),
                description=acct["description"],
            ))
            logger.info(f"Created system account: {acct['id']}")

    db.commit()
